    /// <summary>
    /// PaffH 07.11.25
    /// last modified: PaffH 25.11.25
    /// </summary>
    /// <param name = "_sectionType">NDXBVEmailRequestSectionType</param>
protected void new(NDXBVEmailRequestSectionType _sectionType)
    {
        super(_sectionType);
        NDXBVEmailRequestAIDBFieldContract aiField;
        NDXBVEmailRequestAIDBFieldDecisionBaseContract aiFieldDecisionBase;
        NDXBVEmailRequestAIDBFieldInfoContract aiFieldInfo;
        NDXBVEMailRequestHeaderAIDecisionBasis nDXBVEMailRequestHeaderAIDecisionBasis;

        aiField = NDXBVEmailRequestAIDBFieldContract::construct();
        aiFieldDecisionBase = NDXBVEmailRequestAIDBFieldDecisionBaseContract::constructFromCommon(nDXBVEMailRequestHeaderAIDecisionBasis, fieldNum(NDXBVEMailRequestHeaderAIDecisionBasis, AIDBDocument));
        sectionGroups.addEnd(NDXBVEmailRequestAIDBSectionGroupContract::construct(aiField, aiFieldDecisionBase, aiFieldInfo));
    }

/// <summary>
/// PaffH 07.11.25
/// </summary>
/// <returns>NDXBVEmailRequestAIDBSectionHeaderContract</returns>
public static NDXBVEmailRequestAIDBSectionHeaderAIDBDocumentContract construct()
{
    NDXBVEmailRequestAIDBSectionHeaderAIDBDocumentContract section = new NDXBVEmailRequestAIDBSectionHeaderAIDBDocumentContract(NDXBVEmailRequestSectionType::HeaderAIDBDocument);
    return section;
}
